import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Your first server","description":"","frontmatter":{"pageId":"admins/getting-started","contentRevision":1},"headers":[],"relativePath":"en/admins/getting-started.md","filePath":"en/admins/getting-started.md"}'),n={name:"en/admins/getting-started.md"};function s(o,e,l,d,h,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="your-first-server" tabindex="-1">Your first server <a class="header-anchor" href="#your-first-server" aria-label="Permalink to &quot;Your first server&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><ol><li>Choose a host with persistent storage and reachable TCP 25560. Prepare a private data directory and backups.</li><li>Install a server release or use the container. Pin the image version rather than relying on latest for reproducible recovery.</li><li>Configure TLS, personal authentication, an initial administrator and a separate strong Admin:ApiToken. Password login is disabled by default.</li><li>Start the server, check /health, then verify HTTPS /admin/ login and game login.</li><li>Create the shared world with an administrator client, configure the modpack and invite a test player.</li><li>Create a backup and restore it into a separate test directory before opening publicly.</li></ol><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>An accessible /health does not prove authentication or saving works. Apply a network policy before exposing /metrics and the admin panel. Creating/recreating a world is not a harmless health check.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./hosting">Hosting and startup</a></li><li><a href="./security-auth">TLS, authentication and permissions</a></li><li><a href="./backup-recovery">Backup and recovery</a></li></ul>',8)])])}const m=a(n,[["render",s]]);export{u as __pageData,m as default};
